int get_task_io_priority(struct task_struct *p) {
    int priority;

    if (security_task_get_io_priority(p))
        return -EPERM;

    priority = DEFAULT_IO_PRIORITY;
    if (p->io_context) {
        priority = p->io_context->ioprio;
    } else {
